// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool initialPause, address newOwner, bool finalPause) public {
        // Ensure acceptance can happen: pending owner must be set first
        vm.assume(newOwner != address(0));
        // If we start paused, un-pause first to test in a clean state
        if (initialPause) {
            // Pause via the pause() interface (only owner can)
            vm.prank(c.owner());
            c.pause();
        }
        // Set up a pending owner so acceptOwnership() can succeed
        vm.prank(c.owner());
        c.transferOwnership(newOwner);
        vm.prank(newOwner);
        c.acceptOwnership();
        // Now check the paused() state after optionally finalizing it
        if (finalPause) {
            vm.prank(newOwner);
            c.pause();
        }
        // The general rule: calling pause() sets paused() to true, unpause() sets to false
        // We'll check consistency: since we only ever called pause() or not, paused() must match finalPause
        assertTrue(c.paused() == finalPause);
    }
}

