import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != c.owner());

        bool pausedBefore;
        bool pausedAfter;

        // Read paused state before
        pausedBefore = c.paused();

        // Call acceptOwnership() as non-owner (should revert, but we don't check revert here)
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("acceptOwnership()"));

        // Read paused state after
